def solve(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0

    # Parse the sequence from the top instruction row.
    # Format observed: [color, 0, 0, v1, k1, 0, 0, v2, k2, ... , 0]
    seq = [grid[0][0]]
    for i in range(3, w, 4):
        if i < w:
            seq.append(grid[0][i])

    color = seq[0]

    # Copy grid and clear the top two rows.
    out = [row[:] for row in grid]
    for r in range(min(2, h)):
        for c in range(w):
            out[r][c] = 0

    # Collect positions of the centered numbers inside the 3x3 boxes.
    # These are at rows 3,7,11,... and cols 2,6,10,...
    positions = {}
    center_rows = list(range(3, h, 4))
    center_cols = list(range(2, w, 4))

    for r in center_rows:
        for c in center_cols:
            v = grid[r][c]
            if v != 0 and v != 5:
                positions.setdefault(v, []).append((r, c))

    # Backtracking: choose one occurrence per value so consecutive chosen
    # points lie on the same row or same column.
    candidates = [positions.get(v, []) for v in seq]

    def aligned(a, b):
        return a[0] == b[0] or a[1] == b[1]

    n = len(seq)
    chosen = [None] * n

    def possible_next(idx, pos):
        if idx == n - 1:
            return True
        for nxt in candidates[idx + 1]:
            if aligned(pos, nxt):
                return True
        return False

    def dfs(i):
        if i == n:
            return True
        for pos in candidates[i]:
            if i > 0 and not aligned(chosen[i - 1], pos):
                continue
            if not possible_next(i, pos):
                continue
            chosen[i] = pos
            if dfs(i + 1):
                return True
            chosen[i] = None
        return False

    dfs(0)

    # Draw the path segments in the color.
    for (r1, c1), (r2, c2) in zip(chosen, chosen[1:]):
        if r1 == r2:
            a, b = sorted((c1, c2))
            for c in range(a, b + 1):
                out[r1][c] = color
        else:
            a, b = sorted((r1, r2))
            for r in range(a, b + 1):
                out[r][c1] = color

    return out

